" x2=\"143.1\" y2=\"56\" class=\"guide\"/><text x=\"147.1\" y=\"20\" class=\"tb\" text-anchor=\"start\">mean 80</text><text x=\"404.6\" y=\"44\" class=\"ts2\" text-anchor=\"middle\">founder</text><text x=\"420\" y=\"112\" class=\"ts2\" text-anchor=\"end\">monthly salary (₹ thousand)</text></svg>",
