"></circle><circle cx=\"259.3\" cy=\"25.6\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"184.8\" cy=\"89.8\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"137\" cy=\"100.6\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"145\" cy=\"98.4\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"158.7\" cy=\"104\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"172.9\" cy=\"92.3\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"214.5\" cy=\"60.8\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"172.7\" cy=\"83.7\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"184.6\" cy=\"82.1\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"183.7\" cy=\"77.6\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"188.5\" cy=\"66.2\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"158.8\" cy=\"101.5\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"172.9\" cy=\"78.4\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"206.2\" cy=\"65\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"165.7\" cy=\"82.9\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"158.3\" cy=\"91.2\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"159.2\" cy=\"99.3\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"118.6\" cy=\"124.5\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"161.6\" cy=\"74.8\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"176.7\" cy=\"69.5\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"172\" cy=\"76.6\" r=\"3.5\" class=\"d1\"></circle><circle cx=\"152\" cy=\"89.3\" r=\"3.5\" class=\"d1\"></circle><line x1=\"150\" y1=\"99\" x2=\"228.1\" y2=\"46.2\" class=\"arrk\" marker-end=\"url(#ah-s2p)\"/><line x1=\"150\" y1=\"99\" x2=\"135.3\" y2=\"78.7\" class=\"arrk\" marker-end=\"url(#ah-s2p)\"/><text x=\"232.1\" y=\"40.2\" class=\"tb\" text-anchor=\"start\">PC1</text><text x=\"129.3\" y=\"74.7\" class=\"tb\" text-anchor=\"end\">PC2</text><text x=\"290\" y=\"70\" class=\"t\" text-anchor=\"start\">PC1: the direction of</text><text x=\"290\" y=\"88\" class=\"t\" text-anchor=\"start\">most variation</text><text x=\"290\" y=\"120\" class=\"ts2\" text-anchor=\"start\">Describe each point by its</text><text x=\"290\" y=\"136\" class=\"ts2\" text-anchor=\"start\">position along PC1:</text><text x=\"290\" y=\"152\" class=\"ts2\" text-anchor=\"start\">2 numbers become 1</text></svg>",
