"d1-graph": {
"svg": "<svg viewBox=\"0 0 440 220\" class=\"fig\" role=\"img\" aria-label=\"Fraud-ring detection with a graph. Starting from the flagged account, follow up to three relationships (shared device, shared phone, transfers) to reach suspects A, B and C. In a graph database each hop just follows a stored link; in SQL each hop is another JOIN.\"><defs><marker id=\"ah-d1g\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" class=\"ah\"/></marker><clipPath id=\"cp-d1g\"><rect x=\"0\" y=\"0\" width=\"440\" height=\"220\"/></clipPath></defs><line x1=\"62\" y1=\"110\" x2=\"168\" y2=\"44\" class=\"ax2\"/><line x1=\"62\" y1=\"110\" x2=\"168\" y2=\"176\" class=\"ax2\"/><line x1=\"168\" y1=\"44\" x2=\"318\" y2=\"44\" class=\"ax2\"/><line x1=\"168\" y1=\"176\" x2=\"318\" y2=\"176\" class=\"ax2\"/><line x1=\"318\" y1=\"44\" x2=\"398\" y2=\"110\" class=\"ax2\"/><rect x=\"7\" y=\"94\" width=\"110\" height=\"32\" rx=\"6\" class=\"under\"/><rect x=\"7\" y=\"94\" width=\"110\" height=\"32\" rx=\"6\" class=\"box2\"/><text x=\"62\" y=\"114\" class=\"ts\" text-anchor=\"middle\">Flagged account</text><rect x=\"126\" y=\"28\" width=\"84\" height=\"32\" rx=\"6\" class=\"boxn\"/><text x=\"168\" y=\"48\" class=\"ts\" text-anchor=\"middle\">Device D1</text><rect x=\"126\" y=\"160\" width=\"84\" height=\"32\" rx=\"6\" class=\"boxn\"/><text x=\"168\" y=\"180\" class=\"ts\" text-anchor=\"middle\">Phone P7</text><rect x=\"283\" y=\"28\" width=\"70\" height=\"32\" rx=\"6\" class=\"under\"/><rect x=\"283\" y=\"28\" width=\"70\" height=\"32\" rx=\"6\" class=\"box\"/><text x=\"318\" y=\"48\" class=\"ts\" text-anchor=\"middle\">Acct A</text><rect x=\"283\" y=\"160\" width=\"70\" height=\"32\" rx=\"6\" class=\"under\"/><rect x=\"283\" y=\"160\" width=\"70\" height=\"32\" rx=\"6\" class=\"box\"/><text x=\"318\" y=\"180\" class=\"ts\" text-anchor=\"middle\">Acct C</text><rect x=\"363\" y=\"94\" width=\"70\" height=\"32\" rx=\"6\" class=\"under\"/><rect x=\"363\" y=\"94\" width=\"70\" height=\"32\" rx=\"6\" class=\"box\"/><text x=\"398\" y=\"114\" class=\"ts\" text-anchor=\"middle\">Acct B</text><text x=\"103\" y=\"73\" class=\"ts2\" text-anchor=\"middle\">uses</text><text x=\"103\" y=\"159\" class=\"ts2\" text-anchor=\"middle\">uses</text><text x=\"243\" y=\"38\" class=\"ts2\" text-anchor=\"middle\">used by</text><text x=\"243\" y=\"170\" class=\"ts2\" text-anchor=\"middle\">used by</text><text x=\"374\" y=\"75\" class=\"ts2\" text-anchor=\"middle\">sends ₹</text><text x=\"220\" y=\"214\" class=\"mono\" text-anchor=\"middle\">MATCH (f {flagged:true})-[*1..3]-(s) RETURN s</text></svg>",
"caption": "Fraud-ring detection with a graph. Starting from the flagged account, follow up to three relationships (shared device, shared phone, transfers) to reach suspects A, B and C. In a graph database each hop just follows a stored link; in SQL each hop is another JOIN."
},
